import { Collapsible, CollapsiblePanel, CollapsibleTrigger } from '@gntik-ai/ui';
import { toJson } from '../utils/format';
import { toolCallCardStyles } from './toolCallCard.variants';

const s = toolCallCardStyles.json;

export interface JsonViewProps {
  /** Section title ("Arguments", "Result"). */
  label: string;
  /** Any value: objects are pretty-printed, strings shown as-is. */
  value: unknown;
  defaultOpen?: boolean;
}

/** A small collapsible, scrollable JSON block. */
export function JsonView({ label, value, defaultOpen = true }: JsonViewProps) {
  return (
    <Collapsible defaultOpen={defaultOpen}>
      <CollapsibleTrigger className={s.trigger}>{label}</CollapsibleTrigger>
      <CollapsiblePanel className={s.content}>
        <pre tabIndex={0} aria-label={label} className={s.pre}>
          <code>{toJson(value)}</code>
        </pre>
      </CollapsiblePanel>
    </Collapsible>
  );
}

import { Collapsible, CollapsiblePanel, CollapsibleTrigger, Spinner, StatusTag, cn } from '@gntik-ai/ui';
import { CircleAlert, Wrench } from 'lucide-react';
import type { Ref } from 'react';
import { formatDuration } from '../utils/format';
import { JsonView } from './JsonView';
import { toolCallCardStyles as s } from './toolCallCard.variants';

export type ToolCallStatus = 'running' | 'succeeded' | 'failed';

export interface ToolCallCardProps {
  /** Tool / function name, e.g. "search_invoices". */
  name: string;
  status: ToolCallStatus;
  /** Elapsed time in ms. */
  durationMs?: number;
  /** Arguments the model passed. */
  args?: unknown;
  /** What the tool returned. */
  result?: unknown;
  /** Error message for a failed call. */
  error?: string;
  /** Start expanded. Failed calls open by default. */
  defaultOpen?: boolean;
  /** Controlled open state. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

const VERB: Record<ToolCallStatus, string> = { running: 'Calling', succeeded: 'Called', failed: 'Failed to call' };

/**
 * A tool invocation inside an assistant turn: name, status, duration, and a collapsible body
 * with the arguments and the result (or error) as small JSON views.
 */
export function ToolCallCard({
  name,
  status,
  durationMs,
  args,
  result,
  error,
  defaultOpen,
  open,
  onOpenChange,
  className,
  ref,
}: ToolCallCardProps) {
  const failed = status === 'failed';
  return (
    <Collapsible
      ref={ref}
      defaultOpen={defaultOpen ?? failed}
      open={open}
      onOpenChange={onOpenChange ? (o) => onOpenChange(o) : undefined}
      data-status={status}
      className={cn(s.root, className)}
    >
      <CollapsibleTrigger className={s.trigger}>
        <span className={cn(s.icon, failed && s.iconFailed)}>
          {status === 'running' ? <Spinner size={13} /> : failed ? <CircleAlert size={13} aria-hidden /> : <Wrench size={13} aria-hidden />}
        </span>
        <span className={s.label}>
          <span className={s.verb}>{VERB[status]}</span>
          <span className={s.name}>{name}</span>
        </span>
        <span className={s.meta}>
          {durationMs !== undefined && <span className={s.duration}>{formatDuration(durationMs)}</span>}
          <StatusTag status={status} size="sm" />
        </span>
      </CollapsibleTrigger>
      <CollapsiblePanel className="pt-0">
        <div className={s.body}>
          {args !== undefined && <JsonView label="Arguments" value={args} />}
          {failed && error && (
            <p role="alert" className={s.error}>
              {error}
            </p>
          )}
          {result !== undefined && <JsonView label="Result" value={result} />}
          {status === 'running' && result === undefined && <p className="text-[12.5px] text-muted-foreground">Waiting for the result…</p>}
        </div>
      </CollapsiblePanel>
    </Collapsible>
  );
}

export { ToolCallCard, type ToolCallCardProps, type ToolCallStatus } from './ToolCallCard';
export { JsonView, type JsonViewProps } from './JsonView';
export { toolCallCardStyles } from './toolCallCard.variants';
export { doc as toolCallCardDoc } from './ToolCallCard.doc';

/** Slot classes for ToolCallCard and JsonView. */
export const toolCallCardStyles = {
  root: 'w-full overflow-hidden rounded-lg border border-border bg-card text-[13px]',
  trigger: [
    'flex h-auto w-full min-w-0 justify-start gap-2.5 rounded-none px-3 py-2.5 text-start hover:bg-secondary/50',
    'focus-visible:-outline-offset-2',
  ].join(' '),
  icon: 'grid size-6 shrink-0 place-items-center rounded-md bg-secondary text-muted-foreground',
  iconFailed: 'bg-destructive/15 text-destructive-chip-text',
  label: 'flex min-w-0 flex-1 items-baseline gap-1.5',
  verb: 'shrink-0 text-muted-foreground',
  name: 'truncate font-mono text-[12.5px] font-semibold text-foreground',
  meta: 'flex shrink-0 items-center gap-2',
  duration: 'font-mono text-[11px] text-muted-foreground tabular-nums',
  body: 'flex flex-col gap-2 border-t border-border px-3 pb-3 pt-1',
  error: 'rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-[12.5px] text-destructive-chip-text',
  json: {
    trigger: 'mx-0 h-7 px-1 text-[11.5px] font-semibold tracking-wide text-muted-foreground uppercase',
    content: 'pt-1',
    pre: 'max-h-64 overflow-auto rounded-md border border-border bg-secondary/40 p-2.5 font-mono text-[12px] leading-5 text-foreground',
  },
} as const;

/** "840 ms" below a second, "2.4 s" below a minute, "1 m 05 s" above. */
export function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.round(ms)} ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m} m ${String(s).padStart(2, '0')} s`;
}

/** "12 KB", "3.4 MB". */
export function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Short local time ("14:05") for a message timestamp. */
export function formatTime(date: Date) {
  return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** Pretty-prints any value as JSON; falls back to String() for cyclic or exotic values. */
export function toJson(value: unknown) {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'ToolCallCard',
  group: 'Display',
  status: 'beta',
  description:
    'A tool invocation in an assistant turn: name, status (running, succeeded, failed), duration and a collapsible body with the arguments and the result or error as small collapsible JSON views. Failed calls open by default.',
  primitive: '@base-ui/react/collapsible',
  pattern: 'disclosure',
  keyboard: [
    ['Enter', 'Expands or collapses the card (or a JSON section)'],
    ['Space', 'Expands or collapses the card (or a JSON section)'],
    ['Tab', 'Moves to the JSON sections and their scrollable code'],
  ],
  tokens: ['card', 'border', 'secondary', 'muted-foreground', 'success-text', 'destructive', 'destructive-text', 'focus-ring'],
};
